-- "ともきち的ランキング" on the home page, edited in the admin instead of code.
-- picks is a JSON array of {"articleId", "comment"}, first is #1. A ranking
-- with no picks stays off the site, so the rows seeded here change nothing
-- until the author fills them in.
CREATE TABLE rankings (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  note TEXT NOT NULL DEFAULT '',
  experience_tag TEXT,
  picks TEXT NOT NULL DEFAULT '[]',
  sort_order INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT
);

